{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to correct for overconfidence in downward trends.",
    "Increase forecast sensitivity to recent price spikes (last 5-7 days) when sentiment is positive (sentiment > 0.00) to avoid underreacting to momentum.",
    "Apply mean reversion bias: if forecast is significantly below 30-day moving average, adjust upward by 5-10% to avoid prolonged underestimation.",
    "Reduce forecast volatility after sharp upward spikes (e.g., >10% from prior day) to prevent overshoot and overcorrection.",
    "When sentiment is positive and price is trending upward, apply a lag correction: delay forecast adjustment by 1-2 days to avoid premature reactions.",
    "For long-term horizons (>14 days), reduce forecast magnitude by 5-8% to account for market stabilization and reduced volatility."
  ]
}
